"""Allow work only after its own prerequisites and real dependencies are checked.

Shared file names, reviewer identities and departments are context, not edges.
Callers supply source-grounded checks for each required dependency domain.
"""

from dataclasses import asdict, dataclass
from decimal import Decimal
from typing import Iterable


DOMAINS = frozenset({"evidence", "budget", "authority", "obligations"})


@dataclass(frozen=True)
class Check:
    domain: str
    satisfied: bool
    fact: str
    owner: str
    next_action: str
    source_refs: tuple[str, ...]

    def __post_init__(self):
        if self.domain not in DOMAINS:
            raise ValueError(f"Unknown dependency domain: {self.domain}")
        if not self.fact or not self.owner or not self.next_action or not self.source_refs:
            raise ValueError("A dependency check needs a fact, owner, action and source references")


@dataclass(frozen=True)
class Dependency:
    prerequisite: str
    reason: str
    source_ref: str


@dataclass(frozen=True)
class Work:
    key: str
    checks: tuple[Check, ...]
    dependencies: tuple[Dependency, ...] = ()


def evaluate(work: Iterable[Work]) -> dict[str, dict]:
    """Propagate only explicit, evidenced prerequisites, including unresolved cycles."""
    items = list(work)
    by_key = {item.key: item for item in items}
    if len(by_key) != len(items):
        raise ValueError("Duplicate subject/revision work key")
    results = {}

    def visit(key, path):
        if key in path:
            return {"may_continue": False, "holds": [{"domain": "dependency", "fact": "Cyclic prerequisite: " + " -> ".join((*path, key))}]}
        if key in results:
            return results[key]
        item = by_key[key]
        holds = [asdict(check) for check in item.checks if not check.satisfied]
        missing = DOMAINS - {check.domain for check in item.checks}
        for domain in sorted(missing):
            holds.append({"domain": domain, "fact": "Independence has not been demonstrated", "owner": "Administration", "next_action": "Supply a source-grounded dependency check", "source_refs": []})
        for dep in item.dependencies:
            if not dep.reason or not dep.source_ref:
                raise ValueError("A prerequisite needs a reason and a source reference")
            other = by_key.get(dep.prerequisite)
            if other is None or not visit(dep.prerequisite, (*path, key))["may_continue"]:
                holds.append({"domain": "dependency", "fact": dep.reason, "prerequisite": dep.prerequisite, "source_refs": [dep.source_ref], "owner": "Administration", "next_action": "Resolve or substantiate the prerequisite before continuing dependent work"})
        results[key] = {"may_continue": not holds, "holds": holds}
        return results[key]

    for key in by_key:
        visit(key, ())
    return results


def visible_at(rows: Iterable[dict], batch: int) -> list[dict]:
    """Filter arrival before joining; worksheet order and business time are irrelevant."""
    if type(batch) is not int or batch < 1:
        raise ValueError("Batch must be a positive integer")
    visible = []
    for row in rows:
        arrival = row.get("Arrival batch")
        if isinstance(arrival, bool) or arrival is None or Decimal(str(arrival)) != int(arrival) or int(arrival) < 1:
            raise ValueError("Missing or invalid arrival batch")
        if int(arrival) <= batch:
            visible.append(row)
    return visible


def cents(value) -> int:
    amount = Decimal(str(value)) * 100
    if not amount.is_finite() or amount != amount.to_integral_value():
        raise ValueError("Expected exact integer EUR cents")
    return int(amount)


def budget_remaining(ledger: Iterable[dict], accepted: Iterable[dict]) -> int:
    """Opening allocation minus net settled and remaining prior/new commitments.

    Accepted entries use request_id/amount_cents. Exact redelivery has no extra
    effect; conflicting payloads or missing references cannot prove availability.
    """
    allocation = spent = remaining = 0
    prior = {}
    references = set()
    for row in ledger:
        reference = row["Ledger reference"]
        if not reference or reference in references:
            raise ValueError("Missing or duplicate budget ledger reference")
        references.add(reference)
        value = cents(row["Allocation or commitment (EUR)"])
        if row["Entry type"] == "allocation":
            allocation += value
        elif row["Entry type"] == "obligation":
            obligation = row["Obligation reference"]
            if not obligation or obligation in prior:
                raise ValueError("Missing or duplicate prior obligation")
            settled, refunded = cents(row["Settled (EUR)"]), cents(row["Refunded (EUR)"])
            if min(value, settled, refunded) < 0 or settled > value or refunded > settled:
                raise ValueError("Inconsistent prior budget obligation")
            prior[obligation] = value
            spent += settled - refunded
            remaining += value - settled
        else:
            raise ValueError("Undefined budget entry type")
    requests = {}
    for event in accepted:
        request, amount = event["request_id"], event["amount_cents"]
        if not request or type(amount) is not int or amount <= 0:
            raise ValueError("Invalid accepted commitment")
        if request in requests and requests[request] != amount:
            raise ValueError("Conflicting accepted commitment")
        requests[request] = amount
    for request, amount in requests.items():
        if request in prior:
            if prior[request] != amount:
                raise ValueError("Accepted request conflicts with prior obligation")
        else:
            remaining += amount
    return allocation - spent - remaining

"""Offline source-bound verification of the adopted independence constraint.

This component observes initial-batch evidence, authorizations and commitments.
It does not calculate final entitlement, dispatch requests, close claims, choose
correction scope, or organize the operational repair queue.
"""

import argparse
from datetime import datetime, time, timedelta
from decimal import Decimal
from hashlib import sha256
import json
from pathlib import Path
import re
from zoneinfo import ZoneInfo

from .independence import Check, Work, budget_remaining, cents, evaluate, visible_at


class SourceError(ValueError):
    pass


class Sources:
    def __init__(self, manifest):
        self.path = Path(manifest).resolve()
        self.base = self.path.parent
        self.data = json.loads(self.path.read_text())
        entries = self.data["files"]
        self.files = {e["source_id"]: e for e in entries}
        if len(self.files) != len(entries) or len({e["url"] for e in entries}) != 5:
            raise SourceError("Need unique source IDs and coverage of all five native URLs")
        for entry in entries:
            if entry["status"] != "read":
                raise SourceError("This verification requires complete retained sources")
            path = (self.base / entry["path"]).resolve()
            if not path.is_relative_to(self.base) or sha256(path.read_bytes()).hexdigest() != entry["sha256"]:
                raise SourceError("Missing, unsafe or hash-mismatched retained source: " + entry["source_id"])

    def read(self, source_id):
        entry = self.files[source_id]
        return json.loads((self.base / entry["path"]).read_text(), parse_float=Decimal)

    def table(self, name):
        source_id = "REGISTERS-" + name.upper().replace(" ", "-")
        sheet = self.read(source_id)["sheets"][0]
        rows = sheet["data"][0]["rowData"]
        headers = [v["formattedValue"] for v in rows[4]["values"]]
        result = []
        for index, data in enumerate(rows[5:], 6):
            values = data.get("values", [])
            row = {}
            for column, header in enumerate(headers):
                cell = values[column] if column < len(values) else {}
                value = cell.get("effectiveValue", {})
                if "date" in header.lower() or "time" in header.lower():
                    row[header] = cell.get("formattedValue")
                else:
                    row[header] = next(iter(value.values()), None)
            if any(v is not None for v in row.values()):
                row["_ref"] = f"{source_id}:row{index}"
                result.append(row)
        return result


def field(text, label):
    match = re.search(r"^\s*" + re.escape(label) + r":\s*([^\n]+)", text, re.M)
    if not match:
        raise SourceError("Missing binder field: " + label)
    return match.group(1).strip()


def initial_claims(sources):
    claims = {}
    for page in sources.read("INITIAL-PAGES"):
        text = page["text"]
        lines = [dict(cost_id=m[0], receipt_id=m[1], first_submitted=m[2], gross=Decimal(m[3]), currency=m[4]) for m in re.findall(r"^\s*\d+\s+(\S+)\s+(\S+)\s+(\d{4}-\d{2}-\d{2})\s+(\d+\.\d+)\s+([A-Z]{3})\s*$", text, re.M)]
        if not lines:
            raise SourceError("No expense lines in initial claim page")
        item = dict(id=field(text, "Claim reference"), revision=int(field(text, "Revision")), batch=int(field(text, "Arrival batch")), employee=field(text, "Employee"), trip=field(text, "Trip reference"), trip_revision=int(field(text, "Trip revision")), lines=lines, source_ref=f"INITIAL:page{page['page']}")
        if item["id"] in claims:
            raise SourceError("Ambiguous initial claim identity")
        claims[item["id"]] = item
    return claims


def receipt_records(sources):
    receipts = {}
    for page in sources.read("RECEIPTS-PAGES"):
        for block in re.split(r"(?=Receipt reference:)", page["text"])[1:]:
            key = field(block, "Receipt reference")
            if key in receipts:
                raise SourceError("Duplicate receipt identity")
            receipts[key] = dict(cost_id=field(block, "Expense reference"), employee=field(block, "Employee ID"), trip=field(block, "Trip reference"), currency=field(block, "Currency"), gross=Decimal(field(block, "Gross amount")), source_ref=f"RECEIPTS:page{page['page']}")
    return receipts


def split(value):
    return tuple(str(value).splitlines()) if value else ()


def single(rows, label):
    if len(rows) != 1:
        raise SourceError("Missing or ambiguous " + label)
    return rows[0]


def before_clock(value, sources):
    if not value:
        return False
    event = datetime.strptime(value, "%Y-%m-%d %H:%M:%S UTC").replace(tzinfo=ZoneInfo("UTC"))
    day = datetime.strptime(sources.data["case_clock"], "%Y-%m-%d").date()
    end = datetime.combine(day + timedelta(days=1), time(), ZoneInfo(sources.data["case_timezone"]))
    return event < end


def payment_check(claim, line, receipt, payments):
    """A matching cost ID alone is insufficient; all evidence identities must bind."""
    expected = (line["cost_id"], claim["employee"], claim["trip"], line["currency"], line["gross"])
    receipt_matches = receipt is not None and tuple(receipt[k] for k in ("cost_id", "employee", "trip", "currency", "gross")) == expected
    matching = [r for r in payments if (r["Expense reference"], r["Employee ID"], r["Trip reference"], r["Currency"], r["Gross amount"]) == expected and r["Receipt reference"] == line["receipt_id"] and r["Payment status"] == "settled" and r["Paid date"]]
    ok = receipt_matches and len(matching) == 1
    refs = (claim["source_ref"], receipt["source_ref"] if receipt else "RECEIPTS:all-pages", *(r["_ref"] for r in matching))
    if not matching:
        refs += ("REGISTERS-MERCHANT-PAYMENTS:complete-tab",)
    return Check("evidence", ok, f"{claim['id']} revision {claim['revision']} / {line['cost_id']}: receipt and matching settled merchant proof " + ("verified" if ok else "missing, ambiguous or incompatible"), claim["employee"], f"Supply original receipt and separate settled proof bound to employee, trip, cost, currency, gross and {line['receipt_id']}", refs)


def inspect(manifest, subjects, batch=1):
    if batch != 1:
        raise SourceError("This initial-batch component does not apply correction policy; later-batch implementation awaits learner choice 2")
    sources = Sources(manifest)
    claims = initial_claims(sources)
    receipts = receipt_records(sources)
    people = {r["Employee ID"]: r for r in sources.table("People")}
    trips, payments, ledger = sources.table("Trips"), sources.table("Merchant payments"), sources.table("Budget")
    reviews = visible_at(sources.table("Review ledger"), batch)
    packets = {r["Decision reference"]: r for r in sources.table("Review packets")}
    finance = visible_at(sources.table("Finance activity"), batch)
    cancellations = visible_at(sources.table("Travel cancellations"), batch)
    # Check observed Finance acceptance bindings before using them as shared commitments.
    accepted = []
    for row in finance:
        if row["Activity type"] != "accepted":
            raise SourceError("Initial-budget observer needs a full Finance reducer for non-acceptance outcomes")
        claim = claims.get(row["Claim reference"])
        person = people.get(claim["employee"]) if claim else None
        if not person or row["Finance officer"] != person["Finance officer"] or row["Payee ID"] != person["Payee ID"] or row["Currency"] != "EUR" or not before_clock(row["Activity time (UTC)"], sources):
            raise SourceError("Cannot establish shared budget from incompatible Finance acceptance")
        accepted.append(dict(request_id=row["Request reference"], amount_cents=cents(row["Obligation (EUR)"]), claim=claim, group=tuple(person[k] for k in ("Department", "Project", "Budget period")), source_ref=row["_ref"], event_id=row["Activity reference"]))
    work, observations = [], {}
    for selector in subjects:
        kind, identity, revision_text = selector.split(":")
        revision = int(revision_text)
        if kind == "claim":
            claim = claims.get(identity)
            if not claim or claim["revision"] != revision or claim["batch"] > batch:
                raise SourceError("Claim version is not available in selected batch")
            trip = single([r for r in trips if r["Trip reference"] == claim["trip"] and r["Trip revision"] == claim["trip_revision"]], "claim trip revision")
            person = people[claim["employee"]]
            costs = tuple(line["cost_id"] for line in claim["lines"])
            own = [r for r in accepted if r["claim"]["id"] == identity]
            amount = own[0]["amount_cents"] if len(own) == 1 else None
            checks = [payment_check(claim, line, receipts.get(line["receipt_id"]), payments) for line in claim["lines"]]
            observations[selector] = dict(subject_type=kind, subject_id=identity, revision=revision, trip_id=claim["trip"], trip_revision=claim["trip_revision"], entitlement_cents=None, entitlement_assessment="pending full monetary implementation; never inferred from accepted request", recorded_request_status="accepted" if own else "not_observed", recorded_request_ids=[r["request_id"] for r in own], recorded_obligation_cents=amount, visible_settlement_event_ids=[], confirmed_paid_cents=0, financially_closed=False)
        elif kind == "permit":
            trip = single([r for r in trips if r["Permit reference"] == identity and r["Permit revision"] == revision], "permit revision")
            person = people[trip["Employee ID"]]
            costs = ()
            amount = cents(trip["Estimate (EUR)"])
            own = []
            checks = [Check("evidence", trip["First commitment date"] is None and not any(r["Trip reference"] == trip["Trip reference"] for r in payments), "Separate permit process with no committed or merchant-paid cost observed", "Administration", "Retain trip/permit evidence without inventing a claim", (trip["_ref"], "REGISTERS-MERCHANT-PAYMENTS:complete-tab"))]
            observations[selector] = dict(subject_type=kind, subject_id=identity, revision=revision, trip_id=trip["Trip reference"], trip_revision=int(trip["Trip revision"]), claim_id=None, recorded_estimate_cents=amount, arrangements_paused=False, cancellation_status="not_observed", financially_closed=False)
        else:
            raise SourceError("Subject must be claim or permit")
        if trip["Employee ID"] != person["Employee ID"]:
            raise SourceError("Employee/trip identity conflict")
        group = tuple(person[k] for k in ("Department", "Project", "Budget period"))
        grouped_ledger = [r for r in ledger if tuple(r[k] for k in ("Department", "Project", "Budget period")) == group]
        group_acceptances = [r for r in accepted if r["group"] == group]
        available = budget_remaining(grouped_ledger, group_acceptances)
        checks.append(Check("budget", available >= 0 and (kind == "permit" or amount is not None), f"Shared budget {group}: remaining {available} cents after all observed accepted obligations; own amount " + ("known" if amount is not None else "not yet established"), person["Budget owner"], "Resolve actual funding deficit/unknown commitment before dependent financial readiness", tuple(r["_ref"] for r in grouped_ledger) + tuple(r["source_ref"] for r in group_acceptances)))
        obligations = [r for r in accepted if r["claim"]["id"] != identity and set(costs) & {line["cost_id"] for line in r["claim"]["lines"]}]
        checks.append(Check("obligations", not obligations, "Prior/shared cost obligations " + ("conflict: " + ", ".join(r["request_id"] for r in obligations) if obligations else "checked; no competing accepted request for this cost"), person["Finance officer"], "Resolve duplicate cost/request basis with Finance; preserve existing transfers", ("INITIAL-PAGES:all-claims", "REGISTERS-FINANCE-ACTIVITY:visible-batch1")))
        required = {"administration": person["Administration reviewer"], "budget_owner": person["Budget owner"], "supervisor": person["Supervisor"]}
        if amount is None or amount > 100000:
            required["director"] = person["Director"]
        found = set()
        decision_refs = []
        for row in reviews:
            packet = packets.get(row["Decision reference"])
            if row["Subject type"] != kind or row["Subject reference"] != identity or row["Revision"] != revision or row["Outcome"] != "approve" or not packet or not row["Reason"] or not before_clock(row["Decision time (UTC)"], sources):
                continue
            roles = split(row["Review roles"])
